//! Shared types. Released by the instructor after Checkpoint 1.
//!
//! Every part codes against these definitions. Do not edit this file on your own: if your
//! part needs a change here, raise it with your team and your instructor first.

/// What the player chose from the per-turn menu. Returned by `turn_menu` (Part 2).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TurnChoice {
    StopAtFort,
    Hunt,
    Continue,
}

/// How well the family eats this turn. Chosen in Part 3, stored in
/// `GameState::last_eating_level`, read back by Part 4.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum EatingLevel {
    Poor,
    #[default]
    Moderate,
    Well,
}

/// One variant per outcome of the random-event table. Returned by `roll_random_event`
/// and matched on by `apply_event` (Part 4).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EventKind {
    WagonBreakdown,
    OxInjuredLeg,
    DaughterBrokeArm,
    OxWandersOff,
    SonLost,
    UnsafeWater,
    /// Table slot 7: heavy rain at or below mile 950, cold weather above it.
    RainOrCold,
    Bandits,
    WagonFire,
    HeavyFog,
    Snakebite,
    RiverSwamped,
    WildAnimals,
    HailStorm,
    /// Table slot 15: a silent illness roll that depends on how well the family ate.
    EatingIllnessRoll,
    /// Rolls above the last table threshold.
    HelpfulIndians,
}

/// Every way the trip can end badly. Reaching Oregon City is *not* a variant: arrival is
/// detected separately (mileage has reached 2040) and handled by its own function.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GameOver {
    /// Raised before the eating prompt when food is below 13.
    Starved,
    /// Raised by Part 1's doctor's bill.
    CantAffordDoctor,
    /// Raised by Part 4's illness check.
    RanOutOfMedicalSupplies,
    /// Raised by Part 4's combat outcomes. `resolve_ending` reads `injury_pending` to
    /// choose "INJURIES" or "PNEUMONIA".
    DiedFromInjuryOrIllness,
    /// Raised by Part 1's date advance.
    TrailTooLong,
    /// Raised by Part 4's event table.
    Snakebite,
    /// Raised by Part 3's rider encounter.
    RiderMassacre,
}

/// Everything about the trip in progress. Created by Part 1's `purchase_supplies` and
/// passed (usually as `&mut GameState`) to every other part's functions.
#[derive(Debug, Clone)]
pub struct GameState {
    /// Pounds of food. BASIC `F`.
    pub food: f64,
    /// Number of bullets. BASIC `B`.
    pub bullets: f64,
    /// Clothing. BASIC `C`.
    pub clothing: f64,
    /// Miscellaneous supplies (medicine and repairs). BASIC `M1`.
    pub misc_supplies: f64,
    /// Cash on hand, in dollars. BASIC `T`.
    pub cash: f64,
    /// Dollars spent on the oxen team. Mishaps reduce it. BASIC `A`.
    pub oxen_spend: f64,
    /// Total miles traveled. BASIC `M`.
    pub mileage: f64,
    /// Mileage at the start of the current turn. BASIC `M2`.
    pub turn_start_mileage: f64,
    /// The two-week turn counter. BASIC `D3`.
    pub turn_number: u32,
    /// Shooting skill chosen at the start. BASIC `D9`.
    pub skill_level: f64,
    /// Eating level chosen on the most recent turn. BASIC `E`.
    pub last_eating_level: EatingLevel,
    /// Whether the fort is offered on the turn menu. `turn_menu` reads it to pick the
    /// menu, then flips it for the following turn. Off on the very first turn. BASIC `X1`.
    pub fort_available_next_turn: bool,
    /// Set by a serious illness; read by `apply_doctor_bill` next turn. BASIC `S4`.
    pub illness_pending: bool,
    /// Set by combat outcomes; read by `apply_doctor_bill` and `resolve_ending`. BASIC `K8`.
    pub injury_pending: bool,
    /// One-time mountain checkpoint flag. BASIC `F1`.
    pub south_pass_cleared: bool,
    /// One-time mountain checkpoint flag. BASIC `F2`.
    pub blue_mountains_cleared: bool,
    /// Set when a blizzard fires during the mountain crossing. BASIC `L1`.
    pub blizzard_this_turn: bool,
    /// One-time override: the next status table shows 950 instead of the real mileage.
    /// BASIC `M9`.
    pub force_display_950: bool,
}

impl Default for GameState {
    /// All resources zero, every flag cleared, eating level Moderate.
    fn default() -> GameState {
        GameState {
            food: 0.0,
            bullets: 0.0,
            clothing: 0.0,
            misc_supplies: 0.0,
            cash: 0.0,
            oxen_spend: 0.0,
            mileage: 0.0,
            turn_start_mileage: 0.0,
            turn_number: 0,
            skill_level: 0.0,
            last_eating_level: EatingLevel::Moderate,
            fort_available_next_turn: false,
            illness_pending: false,
            injury_pending: false,
            south_pass_cleared: false,
            blue_mountains_cleared: false,
            blizzard_this_turn: false,
            force_display_950: false,
        }
    }
}
